jsonb) AS row(local_id uuid, target_id uuid, external_id text);

UPDATE _legal_claims incoming
SET person_id = COALESCE(existing.id, person_key.target_id)
FROM _legal_person_keys person_key
LEFT JOIN public.people existing ON existing.external_id = person_key.external_id
WHERE incoming.person_id = person_key.local_id;

DO $$
BEGIN
    IF (SELECT COUNT(*) FROM _legal_claims) <> 136
       OR (SELECT COUNT(*) FROM _legal_person_keys) <> 107
       OR EXISTS (SELECT 1 FROM _legal_claims WHERE source_person_id IS NOT NULL OR candidate_id IS NOT NULL)
       OR EXISTS (SELECT 1 FROM _legal_claims WHERE claim_type <> 'legal_case' OR review_status <> 'verified' OR visibility <> 'public' OR is_public IS DISTINCT FROM TRUE) THEN
        RAISE EXCEPTION 'Reviewed legal production payload drift';
    END IF;
    IF EXISTS (SELECT 1 FROM _legal_claims incoming LEFT JOIN public.people person ON person.id = incoming.person_id WHERE person.id IS NULL OR person.is_public IS DISTINCT FROM TRUE) THEN
        RAISE EXCEPTION 'Reviewed legal production payload references a missing public person';
    END IF;
    IF EXISTS (SELECT 1 FROM public.person_claims existing JOIN _legal_claims incoming ON existing.claim_key = incoming.claim_key WHERE existing.id <> incoming.id)
       OR EXISTS (SELECT 1 FROM public.person_claims existing JOIN _legal_claims incoming ON existing.id = incoming.id WHERE existing.claim_key <> incoming.claim_key) THEN
        RAISE EXCEPTION 'Reviewed legal production claim identifier conflict';
    END IF;
END
$$;

INSERT INTO public.person_claims (id, claim_key, person_id, source_person_id, claim_type, claim_value, claim_json, confidence_level, review_status, visibility, source_name, source_url, observed_at, is_public, created_at, updated_at, review_score, scoring_version, scoring_reasons, auto_reviewed_at, candidate_id)
SELECT id, claim_key, person_id, source_person_id, claim_type, claim_value, claim_json, confidence_level, review_status, visibility, source_name, source_url, observed_at, is_public, created_at, updated_at, review_score, scoring_version, scoring_reasons, auto_reviewed_at, candidate_id FROM _legal_claims
ON CONFLICT (id) DO UPDATE SET
    claim_key = EXCLUDED.claim_key,
    person_id = EXCLUDED.person_id,
    source_person_id = EXCLUDED.source_person_id,
    claim_type = EXCLUDED.claim_type,
    claim_value = EXCLUDED.claim_value,
    claim_json = EXCLUDED.claim_json,
    confidence_level = EXCLUDED.confidence_level,
    review_status = EXCLUDED.review_status,
    visibility = EXCLUDED.visibility,
    source_name = EXCLUDED.source_name,
    source_url = EXCLUDED.source_url,
    observed_at = EXCLUDED.observed_at,
    is_public = EXCLUDED.is_public,
    updated_at = EXCLUDED.updated_at,
    review_score = EXCLUDED.review_score,
    scoring_version = EXCLUDED.scoring_version,
    scoring_reasons = EXCLUDED.scoring_reasons,
    auto_reviewed_at = EXCLUDED.auto_reviewed_at,
    candidate_id = EXCLUDED.candidate_id;

SELECT public.refresh_public_people_list_cached();
SELECT published.promote(NULL);

DO $$
BEGIN
    IF (SELECT COUNT(*) FROM public.person_claims claim JOIN _legal_claims release ON release.id = claim.id WHERE claim.review_status = 'verified' AND claim.visibility = 'public' AND claim.is_public = TRUE) <> 136 THEN
        RAISE EXCEPTION 'Reviewed legal production publication verification failed';
    END IF;
END
$$;

COMMIT;
